shellCommands.command:
/bin/bash -lc "cat <<'EOF' > lib/posts.ts
import { cacheTag } from 'next/cache';

export type Post = {
  id: number;
  title: string;
  createdAt: string;
};

let posts: Post[] = [];
let nextId = 1;

export async function addPost(title: string): Promise<Post> {
  const post: Post = {
    id: nextId++,
    title,
    createdAt: new Date().toISOString(),
  };

  posts = [post, ...posts];
  return post;
}

export async function getPosts(): Promise<Post[]> {
  'use cache';
  cacheTag('posts');
  return posts;
}
EOF"

